## 2. Planets — apparent_planet (calc.rs ~1533)

Add a BARYCTR branch after the existing HELCTR branch:

```
if flags.contains(CalcFlags::BARYCTR) {
    let mut xx = pos.planet_bary;  // already barycentric
    if !flags.contains(CalcFlags::TRUEPOS) {
        // Light-time: same niter=1 pattern as HELCTR but use barycentric distance
        // (no sun_bary subtraction). Re-eval at t-dt, keep planet_bary directly.
        let xx0 = pos.planet_bary;
        let mut dt = 0.0;
        for _ in 0..=1 {
            let dist = |xx|;
            dt = dist * AUNIT / CLIGHT / 86400.0;
            // Analytic extrapolation from barycentric base
            xx[i] = xx0[i] - dt * xx0[i+3];
        }
        let pos_ret = p.positions(body, jd - dt, true)?;
        xx = pos_ret.planet_bary;  // barycentric at retarded time
    }
    return Ok(finish_helctr(xx, jd, flags, models));
}
```

